(2116,'local_outlms_cms','cms_payload_json','{\"header\":{\"brandTitle\":\"LMS\",\"brandShortname\":\"LMS\",\"brandTagline\":\"National Open & Distance University\",\"logoUrl\":\"/assets/img/out-logo.png\",\"showTopbar\":true,\"topbarAddress\":\"Kinondoni, Dar es Salaam\",\"topbarPhone\":\"+255 22 266 8820\",\"topbarEmail\":\"helpdesk@out.ac.tz\",\"announcementBadge\":\"2026/2027 Admissions Open\",\"ctaSignInText\":\"Sign In\",\"ctaRegisterText\":\"Apply Now\",\"navItems\":[{\"id\":\"nav-home\",\"label\":\"Home\",\"route\":\"/index\",\"icon\":\"isax-home-2\",\"visible\":true,\"roles\":[\"guest\",\"student\",\"instructor\",\"admin\"]},{\"id\":\"nav-courses\",\"label\":\"Courses\",\"route\":\"/course/course-grid\",\"icon\":\"isax-book-1\",\"visible\":true,\"roles\":[\"guest\",\"student\",\"instructor\",\"admin\"]},{\"id\":\"nav-faculties\",\"label\":\"Faculties\",\"route\":\"/course/course-category\",\"icon\":\"isax-category\",\"visible\":true,\"roles\":[\"guest\",\"student\",\"instructor\",\"admin\"]},{\"id\":\"nav-instructors\",\"label\":\"Lecturers\",\"route\":\"/pages/instructor-grid\",\"icon\":\"isax-teacher\",\"visible\":true,\"roles\":[\"guest\",\"student\",\"instructor\",\"admin\"]},{\"id\":\"nav-bulletins\",\"label\":\"Notices\",\"route\":\"/blog/blog-grid\",\"icon\":\"isax-note-21\",\"visible\":true,\"roles\":[\"guest\",\"student\",\"instructor\",\"admin\"]},{\"id\":\"nav-about\",\"label\":\"About\",\"route\":\"/pages/about-us\",\"icon\":\"isax-building-4\",\"visible\":true,\"roles\":[\"guest\",\"student\",\"instructor\",\"admin\"]},{\"id\":\"nav-contact\",\"label\":\"Contact\",\"route\":\"/pages/contact-us\",\"icon\":\"isax-call-calling\",\"visible\":true,\"roles\":[\"guest\",\"student\",\"instructor\",\"admin\"]}]},\"hero\":{\"visible\":true,\"eyebrow\":\"TCU Chartered Public University • Flexible Digital Campus\",\"title\":\"Accredited University Education Built Around Your Career\",\"subtitle\":\"Advance your degree, postgraduate, or professional qualification from anywhere in East Africa with self-paced study modules, continuous assessments, and recognized credentials.\",\"searchPlaceholder\":\"Search courses by code (CS101, BBA301), programme title, or faculty...\",\"primaryCtaText\":\"Explore Courses\",\"primaryCtaRoute\":\"/course/course-grid\",\"secondaryCtaText\":\"Scholar Sign In\",\"secondaryCtaRoute\":\"/login\",\"highlights\":[\"TCU & NACTE Accredited\",\"100% Flexible Schedule\",\"Mobile Money & Card Tuition\",\"30+ Regional Centres\"],\"bgImage\":\"/assets/img/home/hero-academic-bg.svg\",\"spotlightCover\":\"/assets/img/home/hero-spotlight-cover.svg\"},\"stats\":{\"visible\":true,\"items\":[{\"id\":\"stat-scholars\",\"label\":\"Active Scholars\",\"value\":\"14,820\",\"badge\":\"Nationwide & EAC\",\"icon\":\"isax-profile-2user\",\"accent\":\"#0171BB\"},{\"id\":\"stat-courses\",\"label\":\"Accredited Courses\",\"value\":\"4\",\"badge\":\"Open Enrolment\",\"icon\":\"isax-book-saved\",\"accent\":\"#0171BB\"},{\"id\":\"stat-faculties\",\"label\":\"Academic Faculties\",\"value\":\"3\",\"badge\":\"Senate Approved\",\"icon\":\"isax-courthouse\",\"accent\":\"#0171BB\"},{\"id\":\"stat-centers\",\"label\":\"Regional Study Centres\",\"value\":\"30+\",\"badge\":\"All Regions\",\"icon\":\"isax-location\",\"accent\":\"#d97706\"}]},\"sections\":{\"faculties\":{\"visible\":true,\"eyebrow\":\"ACADEMIC FACULTIES\",\"title\":\"Explore Programmes by Faculty\",\"subtitle\":\"Choose from accredited degree, diploma, and certificate tracks across our core university faculties.\",\"ctaText\":\"All Faculties\",\"ctaRoute\":\"/course/course-category\"},\"courses\":{\"visible\":true,\"eyebrow\":\"FEATURED PROGRAMMES\",\"title\":\"Popular University Courses\",\"subtitle\":\"Structured digital modules with guided readings, continuous assessments, and official university certification.\",\"ctaText\":\"Browse All Courses\",\"ctaRoute\":\"/course/course-grid\"},\"capabilities\":{\"visible\":true,\"eyebrow\":\"WHY STUDY AT OUT\",\"title\":\"Designed for Working Professionals & Distance Scholars\",\"subtitle\":\"Experience a seamless digital campus from admission to graduation.\",\"cards\":[{\"id\":\"cap-1\",\"title\":\"Self-Paced Digital Classroom\",\"description\":\"Study structured lecture notes, multimedia lessons, and case studies on your own schedule across any device.\",\"badge\":\"24/7 Access\",\"icon\":\"isax-monitor-mobbile\",\"route\":\"/course/course-grid\",\"accent\":\"#0171BB\",\"coverImage\":\"/assets/img/home/feature-self-paced.svg\"},{\"id\":\"cap-2\",\"title\":\"Instant Mobile & Card Tuition\",\"description\":\"Pay module fees via M-Pesa, Airtel Money, Tigo Pesa, or bank card with immediate course activation.\",\"badge\":\"Instant Receipt\",\"icon\":\"isax-wallet-check\",\"route\":\"/pages/pricing-plan\",\"accent\":\"#0171BB\",\"coverImage\":\"/assets/img/home/feature-instant-payment.svg\"},{\"id\":\"cap-3\",\"title\":\"Online Quizzes & Transcripts\",\"description\":\"Complete timed assessments with instant feedback and real-time academic progress tracking.\",\"badge\":\"Auto-Graded\",\"icon\":\"isax-clipboard-tick\",\"route\":\"/student/student-quiz\",\"accent\":\"#0171BB\",\"coverImage\":\"/assets/img/home/feature-online-quiz.svg\"},{\"id\":\"cap-4\",\"title\":\"Verified Digital Certificates\",\"description\":\"Receive official QR-verifiable university certificates and transcripts upon completing your programme.\",\"badge\":\"Senate Verified\",\"icon\":\"isax-award\",\"route\":\"/student/student-certificates\",\"accent\":\"#d97706\",\"coverImage\":\"/assets/img/home/feature-verified-cert.svg\"}],\"bgImage\":\"/assets/img/home/section-why-study-bg.svg\"},\"pathway\":{\"visible\":true,\"eyebrow\":\"ADMISSION PATHWAY\",\"title\":\"Start Learning in 4 Simple Steps\",\"subtitle\":\"From online registration to earning your accredited qualification.\",\"steps\":[{\"step\":\"01\",\"title\":\"Create Scholar Account\",\"description\":\"Register online and select your preferred faculty to get your official student number.\",\"route\":\"/register\",\"coverImage\":\"/assets/img/home/pathway-step-1-account.svg\"},{\"step\":\"02\",\"title\":\"Select & Enrol in Modules\",\"description\":\"Choose your semester courses and complete tuition payment via mobile money or card.\",\"route\":\"/course/course-grid\",\"coverImage\":\"/assets/img/home/pathway-step-2-enrol.svg\"},{\"step\":\"03\",\"title\":\"Study & Take Assessments\",\"description\":\"Complete interactive study units, assignments, and continuous assessment quizzes.\",\"route\":\"/student/student-dashboard\",\"coverImage\":\"/assets/img/home/pathway-step-3-study.svg\"},{\"step\":\"04\",\"title\":\"Graduate with Honours\",\"description\":\"Download your verified academic transcript and official university certificate.\",\"route\":\"/student/student-certificates\",\"coverImage\":\"/assets/img/home/pathway-step-4-graduate.svg\"}]},\"instructors\":{\"visible\":true,\"eyebrow\":\"ACADEMIC LEADERSHIP\",\"title\":\"Learn from Experienced University Lecturers\",\"subtitle\":\"Dedicated professors, senior lecturers, and course coordinators across our departments.\",\"ctaText\":\"All Lecturers\",\"ctaRoute\":\"/pages/instructor-grid\",\"covers\":[\"/assets/img/home/dept-cover-computing.svg\",\"/assets/img/home/dept-cover-ai.svg\",\"/assets/img/home/dept-cover-finance.svg\",\"/assets/img/home/dept-cover-cloud.svg\"]},\"reviews\":{\"visible\":true,\"eyebrow\":\"SCHOLAR STORIES\",\"title\":\"Trusted by Learners Across East Africa\",\"subtitle\":\"Hear from undergraduate and postgraduate scholars advancing their careers with OUT.\",\"items\":[{\"id\":\"rev-1\",\"name\":\"Baraka Mkwawa\",\"role\":\"BSc. ICT Scholar • Dar es Salaam\",\"course\":\"CS101 — Data Structures & Algorithms\",\"rating\":\"5.0\",\"comment\":\"The interactive digital classroom and instant assessment feedback let me balance full-time software engineering work with my degree.\",\"avatar\":\"/assets/img/user/user-02.jpg\",\"coverImage\":\"/assets/img/home/scholar-story-ict.svg\"},{\"id\":\"rev-2\",\"name\":\"Zawadi Bakari\",\"role\":\"BBA Finance Scholar • Arusha Centre\",\"course\":\"BBA301 — Financial Management & Strategy\",\"rating\":\"4.9\",\"comment\":\"Paying tuition via M-Pesa activated my course within seconds, and I downloaded my verified certificate right after completing my final exam.\",\"avatar\":\"/assets/img/user/user-04.jpg\",\"coverImage\":\"/assets/img/home/scholar-story-finance.svg\"},{\"id\":\"rev-3\",\"name\":\"Kelvin Mwita\",\"role\":\"Postgraduate Scholar • Mwanza Centre\",\"course\":\"CS202 — Cloud Computing & Distributed Systems\",\"rating\":\"4.9\",\"comment\":\"Study modules are well structured with clear weekly goals and responsive guidance from faculty lecturers.\",\"avatar\":\"/assets/img/user/user-05.jpg\",\"coverImage\":\"/assets/img/home/scholar-story-cloud.svg\"}]},\"bulletins\":{\"visible\":true,\"eyebrow\":\"UNIVERSITY NOTICES\",\"title\":\"Latest Academic News & Dates\",\"subtitle\":\"Official announcements from the Office of the Deputy Vice-Chancellor (Academic).\",\"ctaText\":\"All Notices\",\"ctaRoute\":\"/blog/blog-grid\",\"items\":[{\"id\":\"bul-1\",\"category\":\"Admissions\",\"date\":\"Nov 2026\",\"title\":\"2026/2027 Semester I Online Course Registration & Orientation Schedule\",\"summary\":\"All continuing and newly admitted scholars can now register for core and elective modules via the self-service portal.\",\"route\":\"/blog/blog-details?id=2\",\"badgeColor\":\"#0171BB\",\"coverImage\":\"/assets/img/home/notice-admissions.svg\"},{\"id\":\"bul-2\",\"category\":\"Examinations\",\"date\":\"Nov 2026\",\"title\":\"Continuous Assessment Quizzes & Regional Examination Guidelines\",\"summary\":\"Review the updated Senate guidelines for online continuous assessments (30%) and regional centre examinations (70%).\",\"route\":\"/blog/blog-details?id=3\",\"badgeColor\":\"#0171BB\",\"coverImage\":\"/assets/img/home/notice-examinations.svg\"},{\"id\":\"bul-3\",\"category\":\"Student Services\",\"date\":\"Nov 2026\",\"title\":\"Digital Campus Portal Upgrade & Instant Tuition Receipts\",\"summary\":\"Experience faster mobile study access, downloadable reading guides, and automated tuition receipts.\",\"route\":\"/blog/blog-details?id=4\",\"badgeColor\":\"#0171BB\",\"coverImage\":\"/assets/img/home/notice-portal-upgrade.svg\"}]},\"ctaBanner\":{\"visible\":true,\"title\":\"Ready to Advance Your Academic & Professional Future?\",\"subtitle\":\"Join over 14,820 scholars studying accredited degree and professional programmes at The Open University of Tanzania.\",\"primaryText\":\"Create Scholar Account\",\"primaryRoute\":\"/register\",\"secondaryText\":\"Apply as Lecturer\",\"secondaryRoute\":\"/pages/become-an-instructor\",\"bgImage\":\"/assets/img/home/cta-banner-bg.svg\"}},\"footer\":{\"orgName\":\"OUT TRAINING\",\"description\":\"A chartered public university established by Act of Parliament No. 17 of 1997, delivering accredited higher education through open and distance learning across East Africa.\",\"accreditationBadge\":\"TCU & NACTE Chartered Public University\",\"address\":\"Kawawa Road, Kinondoni, P.O. Box 23409, Dar es Salaam, Tanzania\",\"phone\":\"+255 22 266 8992 / +255 22 266 8820\",\"email\":\"vc@out.ac.tz / helpdesk@out.ac.tz\",\"newsletterTitle\":\"Academic Newsletter\",\"newsletterSubtitle\":\"Get official registration deadlines, examination dates, and scholarship updates.\",\"copyrightText\":\"© 2026 The Open University of Tanzania (OUT). All Rights Reserved.\",\"columns\":[{\"id\":\"col-faculties\",\"title\":\"Faculties\",\"links\":[{\"label\":\"Science & Technology\",\"route\":\"/course/course-category\"},{\"label\":\"Business Management\",\"route\":\"/course/course-category\"},{\"label\":\"Faculty of Law\",\"route\":\"/course/course-category\"},{\"label\":\"Faculty of Education\",\"route\":\"/course/course-category\"},{\"label\":\"Arts & Social Sciences\",\"route\":\"/course/course-category\"}]},{\"id\":\"col-portals\",\"title\":\"Portals\",\"links\":[{\"label\":\"Scholar Portal\",\"route\":\"/student/student-dashboard\"},{\"label\":\"Lecturer Console\",\"route\":\"/instructor/instructor-dashboard\"},{\"label\":\"University Governance\",\"route\":\"/admin/dashboard\"},{\"label\":\"Verify Certificates\",\"route\":\"/student/student-certificates\"},{\"label\":\"Tuition & Fees\",\"route\":\"/pages/pricing-plan\"}]},{\"id\":\"col-support\",\"title\":\"Quick Links\",\"links\":[{\"label\":\"About OUT\",\"route\":\"/pages/about-us\"},{\"label\":\"Academic FAQ\",\"route\":\"/pages/faq\"},{\"label\":\"Contact Helpdesk\",\"route\":\"/pages/contact-us\"},{\"label\":\"Teach at OUT\",\"route\":\"/pages/become-an-instructor\"}]}],\"socialLinks\":[{\"platform\":\"Facebook\",\"icon\":\"fa-brands fa-facebook-f\",\"url\":\"https://www.facebook.com/outtz\"},{\"platform\":\"X\",\"icon\":\"fa-brands fa-x-twitter\",\"url\":\"https://twitter.com/outtz\"},{\"platform\":\"YouTube\",\"icon\":\"fa-brands fa-youtube\",\"url\":\"https://www.youtube.com/@openuniversityoftanzania\"},{\"platform\":\"LinkedIn\",\"icon\":\"fa-brands fa-linkedin\",\"url\":\"https://www.linkedin.com/school/open-university-of-tanzania\"}],\"bottomLinks\":[{\"label\":\"Academic Regulations\",\"route\":\"/terms-conditions\"},{\"label\":\"Privacy Policy\",\"route\":\"/pages/privacy-policy\"},{\"label\":\"Helpdesk\",\"route\":\"/pages/contact-us\"}]}}'),
