INSERT INTO `mdl_url` VALUES
(2,2,'Lecture 1: Introduction to Algorithms & Computational Thinking','<p>Core principles of computational decomposition, abstraction, pattern recognition, and algorithm design.</p>',1,'https://www.youtube.com/watch?v=1trvO6dqQUI',0,'a:1:{s:10:\"printintro\";i:0;}','a:0:{}',1793521426),
(3,2,'Lecture 2: Pseudocode & Control Flow Architecture','<p>Mastering control flow: sequencing, conditional branching, and iteration loops.</p>',1,'https://www.youtube.com/watch?v=kPRA0W1kECg',0,'a:1:{s:10:\"printintro\";i:0;}','a:0:{}',1793521426),
(4,2,'Lecture 3: Static vs Dynamic Arrays & Memory Addressing','<p>How computer RAM stores contiguous data elements and geometric array resizing strategy.</p>',1,'https://www.youtube.com/watch?v=7hXvfWp6J04',0,'a:1:{s:10:\"printintro\";i:0;}','a:0:{}',1793521426),
(5,2,'Lecture 4: Big-O, Big-Omega, and Big-Theta Notations','<p>Rigorous mathematical definitions of upper bounds, lower bounds, and tight bounds in computer runtime.</p>',1,'https://www.youtube.com/watch?v=__vX2sjlpXU',0,'a:1:{s:10:\"printintro\";i:0;}','a:0:{}',1793521426),
(6,2,'Lecture 5: Divide-and-Conquer - Merge Sort vs Quick Sort','<p>Comparison of recursive divide-and-conquer sorting algorithms with partition analysis.</p>',1,'https://www.youtube.com/watch?v=4VqmGXwpLqc',0,'a:1:{s:10:\"printintro\";i:0;}','a:0:{}',1793521426);
